import AppKit

// MARK: - Locale (NotchAny passes its interface language via UserDefaults["NotchLocale"])
let NOTCH_LOCALE: String = {
    if let l = UserDefaults.standard.string(forKey: "NotchLocale"), !l.isEmpty { return l }
    return Locale.preferredLanguages.first ?? "en"
}()
let EN = NOTCH_LOCALE.lowercased().hasPrefix("en")
@inline(__always) func L(_ zh: String, _ en: String) -> String { EN ? en : zh }

// MARK: - JSON model (order-preserving, raw numbers)
indirect enum JSON {
    case object([(String, JSON)])
    case array([JSON])
    case string(String)
    case number(String)
    case bool(Bool)
    case null

    var isContainer: Bool { switch self { case .object, .array: return true; default: return false } }
    var count: Int { switch self { case .object(let m): return m.count; case .array(let a): return a.count; default: return 0 } }
    var typeName: String {
        switch self {
        case .object(let m): return L("对象 · \(m.count) 键", "Object · \(m.count) keys")
        case .array(let a): return L("数组 · \(a.count) 项", "Array · \(a.count) items")
        case .string: return L("字符串", "String")
        case .number: return L("数字", "Number")
        case .bool: return L("布尔值", "Boolean")
        case .null: return "null"
        }
    }
}

struct JSONError: Error { let message: String; let byteOffset: Int }

struct JSONParser {
    let b: [UInt8]
    var i = 0
    init(_ text: String) { b = Array(text.utf8) }

    mutating func parseDocument() throws -> JSON {
        skipWS()
        let v = try value()
        skipWS()
        if i < b.count { throw fail(L("结尾有多余内容", "Trailing content after the JSON value")) }
        return v
    }
    @inline(__always) mutating func skipWS() {
        while i < b.count { let c = b[i]; if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { i += 1 } else { break } }
    }
    func fail(_ m: String) -> JSONError { JSONError(message: m, byteOffset: i) }
    func isIdentStart(_ c: UInt8) -> Bool { (c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A) || c == 0x5F || c == 0x24 }
    func isIdentChar(_ c: UInt8) -> Bool { isIdentStart(c) || (c >= 0x30 && c <= 0x39) }
    func identifier() -> String {
        var k = i
        while k < b.count, isIdentChar(b[k]) { k += 1 }
        return String(decoding: b[i..<k], as: UTF8.self)
    }
    func charAt() -> String {
        guard i < b.count else { return "" }
        let c = b[i]
        let len = c < 0x80 ? 1 : c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2
        return String(decoding: b[i..<min(b.count, i + len)], as: UTF8.self)
    }

    mutating func value() throws -> JSON {
        skipWS()
        guard i < b.count else { throw fail(L("内容意外结束", "Unexpected end of input")) }
        let c = b[i]
        switch c {
        case UInt8(ascii: "{"):
            i += 1; skipWS()
            var pairs: [(String, JSON)] = []
            if i < b.count, b[i] == UInt8(ascii: "}") { i += 1; return .object(pairs) }
            while true {
                skipWS()
                guard i < b.count else { throw fail(L("缺少 }", "Missing }")) }
                if b[i] != UInt8(ascii: "\"") {
                    if b[i] == UInt8(ascii: "'") { throw fail(L("属性名必须使用双引号", "Property names must use double quotes")) }
                    if isIdentStart(b[i]) { throw fail(L("属性名必须加双引号", "Property names must be quoted")) }
                    throw fail(L("期望属性名", "Expected a property name"))
                }
                let k = try string()
                skipWS()
                guard i < b.count else { throw fail(L("缺少冒号", "Missing colon")) }
                guard b[i] == UInt8(ascii: ":") else { throw fail(L("期望冒号", "Expected a colon")) }
                i += 1
                let v = try value()
                pairs.append((k, v))
                skipWS()
                guard i < b.count else { throw fail(L("缺少 }", "Missing }")) }
                if b[i] == UInt8(ascii: ",") {
                    i += 1; skipWS()
                    if i < b.count, b[i] == UInt8(ascii: "}") { throw fail(L("多余的逗号", "Trailing comma")) }
                    continue
                }
                if b[i] == UInt8(ascii: "}") { i += 1; return .object(pairs) }
                throw fail(L("期望逗号或 }", "Expected , or }"))
            }
        case UInt8(ascii: "["):
            i += 1; skipWS()
            var items: [JSON] = []
            if i < b.count, b[i] == UInt8(ascii: "]") { i += 1; return .array(items) }
            while true {
                items.append(try value())
                skipWS()
                guard i < b.count else { throw fail(L("缺少 ]", "Missing ]")) }
                if b[i] == UInt8(ascii: ",") {
                    i += 1; skipWS()
                    if i < b.count, b[i] == UInt8(ascii: "]") { throw fail(L("多余的逗号", "Trailing comma")) }
                    continue
                }
                if b[i] == UInt8(ascii: "]") { i += 1; return .array(items) }
                throw fail(L("期望逗号或 ]", "Expected , or ]"))
            }
        case UInt8(ascii: "\""):
            return .string(try string())
        case UInt8(ascii: "-"), UInt8(ascii: "0")...UInt8(ascii: "9"):
            return .number(try number())
        case UInt8(ascii: "t"): try literal("true"); return .bool(true)
        case UInt8(ascii: "f"): try literal("false"); return .bool(false)
        case UInt8(ascii: "n"): try literal("null"); return .null
        case UInt8(ascii: "'"): throw fail(L("字符串必须使用双引号", "Strings must use double quotes"))
        case UInt8(ascii: "/"): throw fail(L("JSON 不支持注释", "Comments are not allowed in JSON"))
        default:
            if isIdentStart(c) { throw fail(L("意外的标识符 \"\(identifier())\"", "Unexpected identifier \"\(identifier())\"")) }
            throw fail(L("意外的字符 \"\(charAt())\"", "Unexpected character \"\(charAt())\""))
        }
    }

    mutating func literal(_ word: String) throws {
        let id = identifier()
        guard id == word else { throw fail(L("意外的标识符 \"\(id)\"", "Unexpected identifier \"\(id)\"")) }
        i += word.utf8.count
    }

    mutating func number() throws -> String {
        let start = i
        if b[i] == UInt8(ascii: "-") { i += 1 }
        guard i < b.count, b[i] >= 0x30, b[i] <= 0x39 else { throw fail(L("非法的数字", "Invalid number")) }
        if b[i] == 0x30 { i += 1 } else { while i < b.count, b[i] >= 0x30, b[i] <= 0x39 { i += 1 } }
        if i < b.count, b[i] == UInt8(ascii: ".") {
            i += 1
            guard i < b.count, b[i] >= 0x30, b[i] <= 0x39 else { throw fail(L("非法的数字", "Invalid number")) }
            while i < b.count, b[i] >= 0x30, b[i] <= 0x39 { i += 1 }
        }
        if i < b.count, b[i] == UInt8(ascii: "e") || b[i] == UInt8(ascii: "E") {
            i += 1
            if i < b.count, b[i] == UInt8(ascii: "+") || b[i] == UInt8(ascii: "-") { i += 1 }
            guard i < b.count, b[i] >= 0x30, b[i] <= 0x39 else { throw fail(L("非法的数字", "Invalid number")) }
            while i < b.count, b[i] >= 0x30, b[i] <= 0x39 { i += 1 }
        }
        if i < b.count, (b[i] >= 0x30 && b[i] <= 0x39) || b[i] == UInt8(ascii: ".") || isIdentStart(b[i]) { throw fail(L("非法的数字", "Invalid number")) }
        return String(decoding: b[start..<i], as: UTF8.self)
    }

    mutating func hex4() throws -> UInt32 {
        guard i + 4 <= b.count else { throw fail(L("非法的 \\u 转义", "Invalid \\u escape")) }
        var v: UInt32 = 0
        for k in 0..<4 {
            let c = b[i + k]
            let d: UInt32
            switch c {
            case 0x30...0x39: d = UInt32(c - 0x30)
            case 0x41...0x46: d = UInt32(c - 0x41 + 10)
            case 0x61...0x66: d = UInt32(c - 0x61 + 10)
            default: throw fail(L("非法的 \\u 转义", "Invalid \\u escape"))
            }
            v = v << 4 | d
        }
        i += 4
        return v
    }

    mutating func string() throws -> String {
        i += 1
        var buf: [UInt8] = []
        while true {
            guard i < b.count else { throw fail(L("字符串未闭合", "Unterminated string")) }
            let c = b[i]
            if c == UInt8(ascii: "\"") { i += 1; return String(decoding: buf, as: UTF8.self) }
            if c == UInt8(ascii: "\\") {
                i += 1
                guard i < b.count else { throw fail(L("非法的转义字符", "Invalid escape sequence")) }
                let e = b[i]
                switch e {
                case UInt8(ascii: "\""): buf.append(0x22); i += 1
                case UInt8(ascii: "\\"): buf.append(0x5C); i += 1
                case UInt8(ascii: "/"): buf.append(0x2F); i += 1
                case UInt8(ascii: "b"): buf.append(0x08); i += 1
                case UInt8(ascii: "f"): buf.append(0x0C); i += 1
                case UInt8(ascii: "n"): buf.append(0x0A); i += 1
                case UInt8(ascii: "r"): buf.append(0x0D); i += 1
                case UInt8(ascii: "t"): buf.append(0x09); i += 1
                case UInt8(ascii: "u"):
                    i += 1
                    var cp = try hex4()
                    if cp >= 0xD800 && cp <= 0xDBFF, i + 6 <= b.count, b[i] == UInt8(ascii: "\\"), b[i + 1] == UInt8(ascii: "u") {
                        let save = i
                        i += 2
                        let lo = try hex4()
                        if lo >= 0xDC00 && lo <= 0xDFFF { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00) } else { i = save; cp = 0xFFFD }
                    } else if cp >= 0xD800 && cp <= 0xDFFF { cp = 0xFFFD }
                    let scalar = Unicode.Scalar(cp) ?? "\u{FFFD}"
                    buf.append(contentsOf: Array(String(Character(scalar)).utf8))
                default:
                    throw fail(L("非法的转义字符 \\\(String(decoding: [e], as: UTF8.self))", "Invalid escape \\\(String(decoding: [e], as: UTF8.self))"))
                }
                continue
            }
            if c < 0x20 { throw fail(c == 0x0A ? L("字符串中不能直接换行", "Line break inside a string") : L("字符串中含有控制字符", "Control character inside a string")) }
            buf.append(c); i += 1
        }
    }
}

struct Location { let line: Int; let col: Int; let utf16: Int }
func locate(_ bytes: [UInt8], byteOffset: Int) -> Location {
    var line = 1, col = 1, u16 = 0, k = 0
    let end = min(byteOffset, bytes.count)
    while k < end {
        let c = bytes[k]
        if c == 0x0A { line += 1; col = 1; u16 += 1; k += 1; continue }
        if c & 0xC0 == 0x80 { k += 1; continue }
        col += 1
        u16 += c >= 0xF0 ? 2 : 1
        k += 1
    }
    return Location(line: line, col: col, utf16: u16)
}

// MARK: - Serializer
struct Serializer {
    let indent: String
    let sortKeys: Bool
    var out = ""
    mutating func write(_ v: JSON, depth: Int) {
        switch v {
        case .object(let pairs):
            if pairs.isEmpty { out += "{}"; return }
            let ps = sortKeys ? pairs.sorted { $0.0 < $1.0 } : pairs
            out += "{"
            for (idx, kv) in ps.enumerated() {
                if idx > 0 { out += "," }
                if !indent.isEmpty { out += "\n"; out += String(repeating: indent, count: depth + 1) }
                writeString(kv.0)
                out += indent.isEmpty ? ":" : ": "
                write(kv.1, depth: depth + 1)
            }
            if !indent.isEmpty { out += "\n"; out += String(repeating: indent, count: depth) }
            out += "}"
        case .array(let items):
            if items.isEmpty { out += "[]"; return }
            out += "["
            for (idx, item) in items.enumerated() {
                if idx > 0 { out += "," }
                if !indent.isEmpty { out += "\n"; out += String(repeating: indent, count: depth + 1) }
                write(item, depth: depth + 1)
            }
            if !indent.isEmpty { out += "\n"; out += String(repeating: indent, count: depth) }
            out += "]"
        case .string(let s): writeString(s)
        case .number(let n): out += n
        case .bool(let b): out += b ? "true" : "false"
        case .null: out += "null"
        }
    }
    mutating func writeString(_ s: String) {
        out += "\""
        for u in s.unicodeScalars {
            switch u {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            case "\u{08}": out += "\\b"
            case "\u{0C}": out += "\\f"
            default:
                if u.value < 0x20 { out += String(format: "\\u%04x", u.value) } else { out.unicodeScalars.append(u) }
            }
        }
        out += "\""
    }
}
func serialize(_ v: JSON, indent: String, sortKeys: Bool) -> String {
    var s = Serializer(indent: indent, sortKeys: sortKeys)
    s.out.reserveCapacity(4096)
    s.write(v, depth: 0)
    return s.out
}

// MARK: - Lenient parsing
struct ParseOutcome {
    var value: JSON?
    var notes: [String] = []
    var error: (message: String, loc: Location)?
    var empty = false
}
let trailingComma = try! NSRegularExpression(pattern: ",(\\s*[}\\]])")
func removeTrailingCommas(_ s: String) -> String {
    trailingComma.stringByReplacingMatches(in: s, range: NSRange(location: 0, length: (s as NSString).length), withTemplate: "$1")
}
func strictParse(_ s: String) -> JSON? { var p = JSONParser(s); return try? p.parseDocument() }
func attempt(_ s: String) -> (JSON, Bool)? {
    if let v = strictParse(s) { return (v, false) }
    let fixed = removeTrailingCommas(s)
    if fixed != s, let v = strictParse(fixed) { return (v, true) }
    return nil
}
func smartParse(_ text: String) -> ParseOutcome {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.isEmpty { return ParseOutcome(value: nil, empty: true) }
    var out = ParseOutcome()
    var got = attempt(trimmed)
    if got == nil, let a = trimmed.firstIndex(where: { $0 == "{" || $0 == "[" }) {
        let ends = [trimmed.lastIndex(of: "}"), trimmed.lastIndex(of: "]")].compactMap { $0 }
        if let bEnd = ends.max(), bEnd > a, a != trimmed.startIndex || trimmed.index(after: bEnd) != trimmed.endIndex {
            got = attempt(String(trimmed[a...bEnd]))
            if got != nil { out.notes.append(L("已提取其中的 JSON 片段", "Extracted the embedded JSON fragment")) }
        }
    }
    guard let (first, fixed) = got else {
        var p = JSONParser(text)
        do { _ = try p.parseDocument() } catch let e as JSONError { out.error = (e.message, locate(p.b, byteOffset: e.byteOffset)) } catch {}
        return out
    }
    if fixed { out.notes.append(L("已移除多余的逗号", "Removed trailing commas")) }
    var v = first
    var depth = 0
    while case .string(let s) = v, depth < 3 {
        let t = s.trimmingCharacters(in: .whitespacesAndNewlines)
        guard t.hasPrefix("{") || t.hasPrefix("["), let inner = strictParse(t) else { break }
        v = inner; depth += 1
    }
    if depth > 0 { out.notes.append(L("已解开 \(depth) 层转义字符串", "Unwrapped \(depth) layer(s) of escaped JSON")) }
    out.value = v
    return out
}

// MARK: - Highlight tokenizer
enum TokKind { case key, string, number, bool, null }
struct Token { let range: NSRange; let kind: TokKind }
func tokenize(_ text: String) -> [Token] {
    let b = Array(text.utf8)
    var toks: [Token] = []
    var i = 0, u16 = 0
    @inline(__always) func step() { let c = b[i]; if c & 0xC0 != 0x80 { u16 += c >= 0xF0 ? 2 : 1 }; i += 1 }
    while i < b.count {
        let c = b[i]
        if c == UInt8(ascii: "\"") {
            let startU = u16
            step()
            while i < b.count {
                let d = b[i]
                if d == UInt8(ascii: "\\") { step(); if i < b.count { step() }; continue }
                if d == UInt8(ascii: "\"") { step(); break }
                if d == 0x0A { break }
                step()
            }
            var k = i
            while k < b.count, b[k] == 0x20 || b[k] == 0x09 || b[k] == 0x0A || b[k] == 0x0D { k += 1 }
            let isKey = k < b.count && b[k] == UInt8(ascii: ":")
            toks.append(Token(range: NSRange(location: startU, length: u16 - startU), kind: isKey ? .key : .string))
        } else if c == UInt8(ascii: "-") || (c >= 0x30 && c <= 0x39) {
            let startU = u16
            step()
            while i < b.count, (b[i] >= 0x30 && b[i] <= 0x39) || b[i] == UInt8(ascii: ".") || b[i] == UInt8(ascii: "e") || b[i] == UInt8(ascii: "E") || b[i] == UInt8(ascii: "+") || b[i] == UInt8(ascii: "-") { step() }
            toks.append(Token(range: NSRange(location: startU, length: u16 - startU), kind: .number))
        } else if (c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A) {
            let startU = u16, startI = i
            while i < b.count, (b[i] >= 0x41 && b[i] <= 0x5A) || (b[i] >= 0x61 && b[i] <= 0x7A) || (b[i] >= 0x30 && b[i] <= 0x39) || b[i] == 0x5F { step() }
            let word = String(decoding: b[startI..<i], as: UTF8.self)
            if word == "true" || word == "false" { toks.append(Token(range: NSRange(location: startU, length: u16 - startU), kind: .bool)) }
            else if word == "null" { toks.append(Token(range: NSRange(location: startU, length: u16 - startU), kind: .null)) }
        } else { step() }
    }
    return toks
}

// MARK: - Colors
func dyn(_ light: UInt32, _ dark: UInt32) -> NSColor {
    func c(_ h: UInt32) -> NSColor { NSColor(srgbRed: CGFloat((h >> 16) & 0xFF) / 255, green: CGFloat((h >> 8) & 0xFF) / 255, blue: CGFloat(h & 0xFF) / 255, alpha: 1) }
    return NSColor(name: nil) { app in app.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? c(dark) : c(light) }
}
enum Palette {
    static let key = dyn(0x0B5CAD, 0x9CDCFE)
    static let string = dyn(0xB2341C, 0xCE9178)
    static let number = dyn(0x0F7A4D, 0xB5CEA8)
    static let bool = dyn(0x8F3CC7, 0xC586C0)
    static let null = NSColor.secondaryLabelColor
    static let ok = NSColor.systemGreen
    static let err = NSColor.systemRed
}

// MARK: - Tree node
final class Node {
    let key: String
    let index: Int?
    let value: JSON
    let path: String
    init(key: String, index: Int?, value: JSON, path: String) { self.key = key; self.index = index; self.value = value; self.path = path }
    lazy var children: [Node] = {
        switch value {
        case .object(let ps):
            return ps.map { kv in
                let simple = kv.0.range(of: "^[A-Za-z_$][A-Za-z0-9_$]*$", options: .regularExpression) != nil
                let seg = simple ? ".\(kv.0)" : "[\(serialize(.string(kv.0), indent: "", sortKeys: false))]"
                return Node(key: kv.0, index: nil, value: kv.1, path: path + seg)
            }
        case .array(let items):
            return items.enumerated().map { Node(key: "", index: $0.offset, value: $0.element, path: path + "[\($0.offset)]") }
        default: return []
        }
    }()
}

// MARK: - Line number gutter (separate view beside the scroll view)
final class LineNumberGutter: NSView {
    unowned let textView: NSTextView
    unowned let scrollView: NSScrollView
    var lineStarts: [Int] = [0]
    var widthConstraint: NSLayoutConstraint!
    let numFont = NSFont.monospacedDigitSystemFont(ofSize: 10.5, weight: .regular)
    init(textView: NSTextView, scrollView: NSScrollView) {
        self.textView = textView
        self.scrollView = scrollView
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        clipsToBounds = true
        widthConstraint = widthAnchor.constraint(equalToConstant: 44)
        widthConstraint.isActive = true
    }
    required init?(coder: NSCoder) { fatalError() }
    override var isFlipped: Bool { true }
    override func setFrameSize(_ newSize: NSSize) { super.setFrameSize(newSize); needsDisplay = true }
    func recompute() {
        let u = Array(textView.string.utf16)
        var starts = [0]
        starts.reserveCapacity(u.count / 40 + 1)
        for (idx, c) in u.enumerated() where c == 10 { starts.append(idx + 1) }
        lineStarts = starts
        let digits = max(3, String(starts.count).count)
        let w = CGFloat(digits) * 7 + 18
        if widthConstraint.constant != w { widthConstraint.constant = w }
        needsDisplay = true
    }
    func lineIndex(forCharAt loc: Int) -> Int? {
        var lo = 0, hi = lineStarts.count - 1
        while lo <= hi {
            let mid = (lo + hi) / 2
            if lineStarts[mid] == loc { return mid }
            if lineStarts[mid] < loc { lo = mid + 1 } else { hi = mid - 1 }
        }
        return nil
    }
    override func draw(_ dirtyRect: NSRect) {
        NSColor.textBackgroundColor.setFill()
        bounds.fill()
        NSColor.separatorColor.setFill()
        NSRect(x: bounds.maxX - 1, y: 0, width: 1, height: bounds.height).fill()
        guard let lm = textView.layoutManager, let tc = textView.textContainer else { return }
        let visible = textView.visibleRect
        let glyphRange = lm.glyphRange(forBoundingRect: visible, in: tc)
        let offsetY = textView.textContainerInset.height - visible.minY
        let attrs: [NSAttributedString.Key: Any] = [.font: numFont, .foregroundColor: NSColor.tertiaryLabelColor]
        let w = bounds.width
        func drawNum(_ n: Int, _ frag: NSRect) {
            let str = String(n) as NSString
            let size = str.size(withAttributes: attrs)
            let y = frag.minY + offsetY + (frag.height - size.height) / 2
            if y + size.height < 0 || y > bounds.height { return }
            str.draw(at: NSPoint(x: w - 8 - size.width, y: y), withAttributes: attrs)
        }
        var g = glyphRange.location
        let end = NSMaxRange(glyphRange)
        while g < end {
            var eff = NSRange()
            let frag = lm.lineFragmentRect(forGlyphAt: g, effectiveRange: &eff, withoutAdditionalLayout: true)
            let charStart = lm.characterIndexForGlyph(at: g)
            if let li = lineIndex(forCharAt: charStart) { drawNum(li + 1, frag) }
            if eff.length == 0 { break }
            g = NSMaxRange(eff)
        }
        if lm.extraLineFragmentTextContainer != nil { drawNum(lineStarts.count, lm.extraLineFragmentRect) }
    }
}

