    // MARK: text handling
    func setEditorText(_ s: String) {
        programmatic = true
        let full = NSRange(location: 0, length: (textView.string as NSString).length)
        if textView.shouldChangeText(in: full, replacementString: s) {
            textView.textStorage?.replaceCharacters(in: full, with: s)
            textView.didChangeText()
        }
        programmatic = false
        textView.setSelectedRange(NSRange(location: 0, length: 0))
        scrollView.contentView.scroll(to: .zero)
        scrollView.reflectScrolledClipView(scrollView.contentView)
    }
    func applyBaseAttributes() {
        guard let ts = textView.textStorage else { return }
        let full = NSRange(location: 0, length: ts.length)
        ts.beginEditing()
        ts.setAttributes([.font: mono, .foregroundColor: NSColor.textColor, .paragraphStyle: paragraph], range: full)
        if ts.length < 800_000 {
            for t in tokenize(textView.string) {
                let c: NSColor
                switch t.kind { case .key: c = Palette.key; case .string: c = Palette.string; case .number: c = Palette.number; case .bool: c = Palette.bool; case .null: c = Palette.null }
                if NSMaxRange(t.range) <= ts.length { ts.addAttribute(.foregroundColor, value: c, range: t.range) }
            }
        }
        ts.endEditing()
    }
    func textDidChange(_ n: Notification) {
        gutter.recompute()
        if programmatic { return }
        pending?.cancel()
        let work = DispatchWorkItem { [weak self] in self?.validateTyped() }
        pending = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18, execute: work)
    }
    func validateTyped() {
        let t = editorText
        applyBaseAttributes()
        if t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { current = nil; setChip(nil); setMsg(""); rebuildTree(); updateStat(); return }
        var p = JSONParser(t)
        do {
            current = try p.parseDocument()
            setChip(true); setMsg("")
        } catch let e as JSONError {
            current = nil; setChip(false)
            let loc = locate(p.b, byteOffset: e.byteOffset)
            setMsg(L("第 \(loc.line) 行第 \(loc.col) 列：\(e.message)", "Line \(loc.line), column \(loc.col): \(e.message)"), error: true)
        } catch {}
        rebuildTree(); updateStat()
    }
    func textView(_ tv: NSTextView, doCommandBy sel: Selector) -> Bool {
        if sel == #selector(NSResponder.insertNewline(_:)) {
            let s = tv.string as NSString
            let loc = tv.selectedRange().location
            let lineRange = s.lineRange(for: NSRange(location: loc, length: 0))
            var ws = ""
            var k = lineRange.location
            while k < loc { let c = s.character(at: k); if c == 0x20 || c == 0x09 { ws.append(c == 0x20 ? " " : "\t"); k += 1 } else { break } }
            tv.insertText("\n" + ws, replacementRange: tv.selectedRange())
            return true
        }
        if sel == #selector(NSResponder.insertTab(_:)) { tv.insertText(indentUnit, replacementRange: tv.selectedRange()); return true }
        return false
    }

    /// Parse the given text leniently, write the formatted result into the editor.
    func applySmart(_ text: String, compact: Bool, source: String?) {
        pending?.cancel()
        let o = smartParse(text)
        if o.empty { current = nil; setChip(nil); setMsg(L("没有内容", "No content")); rebuildTree(); updateStat(); return }
        if let v = o.value {
            current = v
            setEditorText(serialize(v, indent: compact ? "" : indentUnit, sortKeys: sortCheck.state == .on))
            applyBaseAttributes()
            setChip(true)
            setMsg(o.notes.joined(separator: "，"))
        } else {
            current = nil
            if editorText != text { setEditorText(text) }
            applyBaseAttributes()
            setChip(false)
            if let e = o.error {
                setMsg(L("第 \(e.loc.line) 行第 \(e.loc.col) 列：\(e.message)", "Line \(e.loc.line), column \(e.loc.col): \(e.message)"), error: true)
                let len = (textView.string as NSString).length
                let r = NSRange(location: min(e.loc.utf16, len), length: e.loc.utf16 < len ? 1 : 0)
                textView.setSelectedRange(r)
                textView.scrollRangeToVisible(r)
                window.makeFirstResponder(textView)
            } else { setMsg(L("JSON 无法解析", "Cannot parse JSON"), error: true) }
        }
        if let s = source { window.subtitle = s }
        rebuildTree(); updateStat()
    }

    // MARK: actions
    func loadClipboard(onlyIfChanged: Bool) {
        let pb = NSPasteboard.general
        if onlyIfChanged && pb.changeCount == lastChange { return }
        lastChange = pb.changeCount
        guard let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            if !onlyIfChanged { setMsg(L("剪贴板中没有文本，可直接粘贴或输入", "No text on the clipboard — paste or type here"), error: false); updateStat() }
            return
        }
        let f = DateFormatter(); f.dateFormat = "HH:mm:ss"
        applySmart(s, compact: false, source: L("来自剪贴板 · ", "From clipboard · ") + f.string(from: Date()))
    }
    @objc func readClipboardAction() { loadClipboard(onlyIfChanged: false) }
    @objc func formatAction() { applySmart(editorText, compact: false, source: nil) }
    @objc func minifyAction() { applySmart(editorText, compact: true, source: nil) }
    @objc func optionsChanged() {
        UserDefaults.standard.set(indentPopup.indexOfSelectedItem, forKey: "indent")
        UserDefaults.standard.set(sortCheck.state == .on, forKey: "sortKeys")
        if current != nil { applySmart(editorText, compact: false, source: nil) }
    }
    @objc func copyAllAction() {
        let t = editorText
        guard !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { setMsg(L("没有可复制的内容", "Nothing to copy"), error: true); return }
        let pb = NSPasteboard.general; pb.clearContents(); pb.setString(t, forType: .string)
        lastChange = pb.changeCount
        setMsg(L("已复制到剪贴板", "Copied to clipboard"))
    }
    @objc func clearAction() {
        setEditorText(""); current = nil; setChip(nil); setMsg(""); window.subtitle = ""; rebuildTree(); updateStat()
        window.makeFirstResponder(textView)
    }

    // MARK: tree
    func rebuildTree() {
        root = current.map { Node(key: "", index: nil, value: $0, path: "$") }
        outline.reloadData()
        pathLabel.stringValue = ""
        guard let r = root else { return }
        outline.expandItem(r)
        if r.children.count <= 50 { for c in r.children where c.value.isContainer && c.value.count <= 50 { outline.expandItem(c) } }
    }
    @objc func expandAll() { if root == nil, current == nil { formatAction() }; outline.expandItem(nil, expandChildren: true) }
    @objc func collapseAll() { outline.collapseItem(nil, collapseChildren: true); if let r = root { outline.expandItem(r) } }
    @objc func copyNodeValue(_ sender: Any?) {
        let row = outline.clickedRow
        guard row >= 0, let n = outline.item(atRow: row) as? Node else { return }
        let text: String
        switch n.value { case .string(let s): text = s; default: text = serialize(n.value, indent: n.value.isContainer ? indentUnit : "", sortKeys: false) }
        let pb = NSPasteboard.general; pb.clearContents(); pb.setString(text, forType: .string)
        lastChange = pb.changeCount
        let preview = text.count > 60 ? String(text.prefix(60)) + "…" : text
        setMsg(L("已复制 ", "Copied ") + (n.value.isContainer ? n.path : L("值：", "value: ") + preview.replacingOccurrences(of: "\n", with: " ")))
    }
    func outlineView(_ ov: NSOutlineView, numberOfChildrenOfItem item: Any?) -> Int { item == nil ? (root == nil ? 0 : 1) : (item as! Node).children.count }
    func outlineView(_ ov: NSOutlineView, child index: Int, ofItem item: Any?) -> Any { item == nil ? root! : (item as! Node).children[index] }
    func outlineView(_ ov: NSOutlineView, isItemExpandable item: Any) -> Bool { let n = item as! Node; return n.value.isContainer && n.value.count > 0 }
    func outlineView(_ ov: NSOutlineView, viewFor col: NSTableColumn?, item: Any) -> NSView? {
        let n = item as! Node
        let id = col?.identifier ?? NSUserInterfaceItemIdentifier("key")
        let cell = (ov.makeView(withIdentifier: id, owner: nil) as? NSTableCellView) ?? {
            let c = NSTableCellView(); c.identifier = id
            let tf = NSTextField(labelWithString: ""); tf.translatesAutoresizingMaskIntoConstraints = false; tf.lineBreakMode = .byTruncatingTail; tf.font = .monospacedSystemFont(ofSize: 12, weight: .regular)
            c.addSubview(tf); c.textField = tf
            NSLayoutConstraint.activate([tf.leadingAnchor.constraint(equalTo: c.leadingAnchor, constant: 2), tf.trailingAnchor.constraint(equalTo: c.trailingAnchor, constant: -2), tf.centerYAnchor.constraint(equalTo: c.centerYAnchor)])
            return c
        }()
        let f = NSFont.monospacedSystemFont(ofSize: 12, weight: .regular)
        if id.rawValue == "key" {
            if n.index != nil { cell.textField?.attributedStringValue = NSAttributedString(string: String(n.index!), attributes: [.font: f, .foregroundColor: NSColor.tertiaryLabelColor]) }
            else if n.path == "$" { cell.textField?.attributedStringValue = NSAttributedString(string: "$", attributes: [.font: f, .foregroundColor: NSColor.secondaryLabelColor]) }
            else { cell.textField?.attributedStringValue = NSAttributedString(string: n.key, attributes: [.font: f, .foregroundColor: Palette.key]) }
        } else {
            let s: String; let c: NSColor
            switch n.value {
            case .object(let ps): s = ps.isEmpty ? "{ }" : L("{ \(ps.count) 键 }", "{ \(ps.count) keys }"); c = .tertiaryLabelColor
            case .array(let a): s = a.isEmpty ? "[ ]" : L("[ \(a.count) 项 ]", "[ \(a.count) items ]"); c = .tertiaryLabelColor
            case .string(let v): s = serialize(.string(v.count > 300 ? String(v.prefix(300)) + "…" : v), indent: "", sortKeys: false); c = Palette.string
            case .number(let v): s = v; c = Palette.number
            case .bool(let v): s = v ? "true" : "false"; c = Palette.bool
            case .null: s = "null"; c = Palette.null
            }
            cell.textField?.attributedStringValue = NSAttributedString(string: s, attributes: [.font: f, .foregroundColor: c])
        }
        return cell
    }
    func outlineViewSelectionDidChange(_ n: Notification) {
        let row = outline.selectedRow
        pathLabel.stringValue = row >= 0 ? ((outline.item(atRow: row) as? Node)?.path ?? "") : ""
    }
    func splitView(_ sv: NSSplitView, constrainMinCoordinate p: CGFloat, ofSubviewAt i: Int) -> CGFloat { 240 }
    func splitView(_ sv: NSSplitView, constrainMaxCoordinate p: CGFloat, ofSubviewAt i: Int) -> CGFloat { sv.bounds.width - 240 }
}

